  function applyPrayConfirmPrefabLayout(count){
    if(!isPrayConfirmPopupScene)return;
    count=Math.max(1,Math.min(5,Math.round(num(count,1))));
    const listHeight=prayConfirmListHeight(count),bodyHeight=listHeight+40,mainHeight=bodyHeight+160;
    // P137 backports the user-PASS P136-WebFix1 registration instead of the earlier raw -100px guess.
    // The real-game screenshot is ~1.04x larger than the raw prefab while the sanctuary background aligns.
    gameplayRuntimeScale.set(prayConfirmPopupPaths.frame,{x:1.04,y:1.04,z:1});
    // Registered coordinates place the popup about 15 reference pixels lower than raw Transform(-25).
    gameplayRuntimePosition.set(prayConfirmPopupPaths.frame,{x:0,y:-40});
    gameplaySetField(prayConfirmPopupPaths.mainBg2,"mHeight",bodyHeight);
    gameplaySetField(prayConfirmPopupPaths.mainBg,"mHeight",mainHeight);
    gameplayRuntimePosition.set(prayConfirmPopupPaths.title,{x:0,y:bodyHeight/2+102});
    gameplayRuntimePosition.set(prayConfirmPopupPaths.desc,{x:0,y:bodyHeight/2+30});
    gameplayRuntimePosition.set(prayConfirmPopupPaths.buttons,{x:0,y:-49-bodyHeight/2});
    // Current-build CUILayoutGroupFlexible: TopToBot, spacing=2, 444x48 CUILayoutElement rows.
    const firstY=(listHeight/2)-24;
    for(let slot=0;slot<5;slot++){
      const base=prayConfirmSlotBase(slot);
      gameplayRuntimePosition.set(base,{x:0,y:firstY-slot*50});
    }
    // With one row the 60px minimum List is 12px taller than its 48px child; cancel the +6px TopToBot offset.
    // Multi-row states require no extra List offset after screenshot registration.
    gameplayRuntimePosition.set(prayConfirmPopupPaths.list,{x:0,y:count===1?-6:0});
  }
  function applyPrayConfirmPopupState(d){
    if(!isPrayConfirmPopupScene)return;
    const slotCount=Math.max(0,Math.min(5,Math.round(num(d&&d.slotCount,0)))),slots=Array.isArray(d&&d.slots)?d.slots:[],locks=Array.isArray(d&&d.locks)?d.locks:[];
    // P137 backports the user-PASS P136-WebFix2 behavior: PrayConfirmPopup lists only rows that will reroll.
    // Locked rows are preserved by Pray, so omit them, retain source-slot order, and compact the visible list.
    const visibleEntries=[];
    for(let sourceSlot=0;sourceSlot<slotCount;sourceSlot++){
      if(Boolean(locks[sourceSlot]))continue;
      visibleEntries.push({sourceSlot,outcome:slots[sourceSlot]||null});
    }
    gameplayRuntimeText.set(prayConfirmPopupPaths.titleText,"祈禱確認");
    gameplayRuntimeText.set(prayConfirmPopupPaths.desc,"如下祝福會依照各機率重新設定。");
    gameplayRuntimeText.set(prayConfirmPopupPaths.cancelLabel,"取消");
    gameplayRuntimeText.set(prayConfirmPopupPaths.confirmLabel,"確認");
    // All-locked popup geometry remains outside the evidence-closed scope; partial-lock behavior is user-PASS.
    applyPrayConfirmPrefabLayout(Math.max(1,visibleEntries.length));
    for(let row=0;row<5;row++){
      const base=prayConfirmSlotBase(row),entry=visibleEntries[row]||null,visible=Boolean(entry),outcome=entry&&entry.outcome||null;
      gameplayRuntimeActive.set(base,visible);
      gameplayRuntimeActive.set(base+"/BlessList_A",Boolean(visible&&outcome));
      gameplayRuntimeActive.set(base+"/BlessList_E",Boolean(visible&&!outcome));
      if(outcome){
        const text=String(outcome.displayText||"");
        gameplayRuntimeText.set(base+"/BlessList_A/Txt",text);
        const sprite=gameplayGradeSprite[String(outcome.gradeName||"")]||"";
        if(sprite)gameplaySetField(base+"/BlessList_A/Grade","mSpriteName",sprite);
      }else if(visible){
        gameplayRuntimeText.set(base+"/BlessList_E/Txt","透過祈禱獲得祝福吧。");
      }else{
        gameplayRuntimeText.delete(base+"/BlessList_A/Txt");
        gameplayRuntimeText.delete(base+"/BlessList_E/Txt");
      }
    }
    activeCache.clear();worldCache.clear();draw();
  }
